const RP = LAY.route.points.map(V3), RDS = LAY.route.ds, RBANK = LAY.route.bank ?? RP.map(() => 0), RLEN = (RP.length - 1) * RDS;
const at = (s, out) => { const x = Math.min(Math.max(s / RDS, 0), RP.length - 1.0001), i = Math.floor(x), f = x - i; return out.copy(RP[i]).lerp(RP[i + 1], f); };
const _a = new THREE.Vector3(), _b = new THREE.Vector3();
const frameAt = (s) => { at(Math.min(RLEN, s + 0.06), _a); at(Math.max(0, s - 0.06), _b); const t = _a.clone().sub(_b).normalize();
  const r0 = new THREE.Vector3().crossVectors(t, UPV).normalize(), n0 = new THREE.Vector3().crossVectors(r0, t).normalize();
  const x = Math.min(Math.max(s / RDS, 0), RP.length - 1.0001), i = Math.floor(x), b = lerp(RBANK[i], RBANK[i + 1], x - i);
  const r = r0.clone().multiplyScalar(Math.cos(b)).addScaledVector(n0, Math.sin(b)), n = n0.clone().multiplyScalar(Math.cos(b)).addScaledVector(r0, -Math.sin(b));
  return { t, r, n }; };
const S_REF = LAY.cams[0].s_ref ?? 0, LEVEL = Math.min(RLEN - 1.0, LAY.level_end ?? RLEN - 1.0);
const DRUM = LAY.drum;   // optional washer drum (axis along -z): glow at its far end, camera clamp inside it

// ---------------- code materials (where no picture saw a surface): the same style as the pictures, drawn at load ----------------
const cvs = (w, h, draw) => { const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8; t.colorSpace = THREE.NoColorSpace; return t; };
const rnd = (() => { let x = 4343; return () => ((x = (x * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff); })();
const grad = (g, x0, y0, x1, y1, stops) => { const gr = g.createLinearGradient(x0, y0, x1, y1); for (const [o, c] of stops) gr.addColorStop(o, c); return gr; };
const PAL = { wallA: '#902a75', wallB: '#f069e4', wallM: '#ba3bb0', slot: '#2a0533', ...(LAY.palette ?? {}) };   // r43b: measured on the approved 06 walls (p20 / p80 / median)
const BASE = {
  // drum wall where no painted pixel is sharp enough (seen close): the painted wall's look - violet-to-pink polished metal (colours sampled
  // from the approved walls), light streaks along the drum, rows of dark capsule slots with a light lower rim. Tile = 8 slots x 4 rows.
  tunnel: cvs(1024, 512, (g, w, h) => { g.fillStyle = grad(g, 0, 0, w, 0, [[0, PAL.wallA], [0.25, PAL.wallB], [0.5, PAL.wallM], [0.75, PAL.wallB], [1, PAL.wallA]]); g.fillRect(0, 0, w, h);
    g.globalCompositeOperation = 'lighter'; for (let i = 0; i < 14; i++) { const x = rnd() * w; g.fillStyle = `rgba(255,${200 + rnd() * 40},255,${0.08 + rnd() * 0.12})`; g.fillRect(x, 0, 3 + rnd() * 14, h); } g.globalCompositeOperation = 'source-over';
    for (let r = 0; r < 4; r++) for (let i = 0; i < 8; i++) { const x = (i + 0.5 + (r % 2) * 0.5) * w / 8, y = (r + 0.5) * h / 4, rx = w / 8 * 0.33, ry = h / 4 * 0.16;
      g.fillStyle = 'rgba(255,225,255,0.85)'; g.beginPath(); g.ellipse(x, y + ry * 0.55, rx * 1.04, ry * 1.1, 0, 0, 7); g.fill();
      const sg = g.createLinearGradient(0, y - ry, 0, y + ry); sg.addColorStop(0, '#1c0533'); sg.addColorStop(1, PAL.slot); g.fillStyle = sg; g.beginPath(); g.ellipse(x, y, rx, ry, 0, 0, 7); g.fill(); } }),
  goldring: cvs(1024, 128, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#a8560f'], [0.2, '#f6b04a'], [0.35, '#ffe39a'], [0.5, '#e8902c'], [0.75, '#ffcc66'], [1, '#8a4210']]); g.fillRect(0, 0, w, h);

