import { installControls } from './controls.js';
const q = new URLSearchParams(location.search);
for (const [k, v] of [['c_LANE', '0.3'], ['c_LAT_MAX', '0.36'], ['speed', '2.2']]) if (!q.has(k)) q.set(k, v);
const W = +(q.get('w') ?? innerWidth), H = +(q.get('h') ?? innerHeight);
const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
renderer.setPixelRatio(q.get('w') ? 1 : Math.min(2, devicePixelRatio)); renderer.setSize(W, H); document.body.appendChild(renderer.domElement);
const SEC = await (await fetch('section.json')).json(), T = SEC.tunnel, CH = SEC.chamber;
const V3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);
const scene = new THREE.Scene(); scene.background = new THREE.Color(q.get('sentinel') ? 0x00ff00 : 0x1a0630);   // ?sentinel=1: holes show pure green
const camera = new THREE.PerspectiveCamera(SEC.fov, W / H, 0.03, 300); camera.rotation.order = 'YXZ';
const world = new THREE.Group(); world.name = 'world'; scene.add(world);
const lerp = (a, b, x) => a + (b - a) * x, sstep = (a, b, x) => { const k = Math.min(1, Math.max(0, (x - a) / (b - a))); return k * k * (3 - 2 * k); };
const DEG = Math.PI / 180;

// ---------------- route = the painted river's centre line (fit_section.py), Benny's path ----------------
const RT = SEC.route; const RX = (z) => { const x = Math.min(Math.max((-z - RT.z0) / RT.ds, 0), RT.x.length - 1.001), i = Math.floor(x), f = x - i; return RT.x[i] + (RT.x[i + 1] - RT.x[i]) * f; };
const PB = V3(SEC.benny.bubble), PBS = V3(SEC.benny.sock), ZB0 = PB.z, S_SOCK = PB.z - PBS.z;
const zOf = (s) => ZB0 - s;
const at = (s, out) => { const z = zOf(s); return out.set(RX(z), 0, z); };
const frameAt = (s) => { const z = zOf(s), k = (RX(z - 0.05) - RX(z + 0.05)) / 0.1; const t = new THREE.Vector3(k, 0, -1).normalize(); return { t, r: new THREE.Vector3(-t.z, 0, t.x), n: new THREE.Vector3(0, 1, 0) }; };
const Z_EXIT = T.z_exit, LEVEL = ZB0 - (T.z_level_end ?? (Z_EXIT - 4.5));   // r41: the level ends INSIDE the continuing tube (the game takes over there)
const radius = (z) => z >= T.funnel[0] ? T.r_arch_in : z >= T.funnel[1] ? lerp(T.r_arch_in, T.r_sock, sstep(T.funnel[0], T.funnel[1], z)) : T.r_sock;
const axy = (z) => z >= T.funnel[0] ? T.axis_y_arch : z >= T.funnel[1] ? lerp(T.axis_y_arch, T.axis_y_sock, sstep(T.funnel[0], T.funnel[1], z)) : T.axis_y_sock;

// ---------------- code materials (where no picture saw a surface): same style as the pictures, drawn at load ----------------
const cvs = (w, h, draw) => { const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8; t.colorSpace = THREE.NoColorSpace; return t; };
const rnd = (() => { let x = 4040; return () => ((x = (x * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff); })();
const grad = (g, x0, y0, x1, y1, stops) => { const gr = g.createLinearGradient(x0, y0, x1, y1); for (const [o, c] of stops) gr.addColorStop(o, c); return gr; };
const BASE = {
  pink: cvs(512, 512, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#e0539f'], [0.5, '#f582c4'], [1, '#e0539f']]); g.fillRect(0, 0, w, h);
    for (let r = 0; r < 4; r++) for (let i = 0; i < 4; i++) { const x = (i + 0.5 + (r % 2) * 0.5) * w / 4, y = (r + 0.5) * h / 4, R = 30;
      g.fillStyle = 'rgba(255,210,236,0.9)'; g.beginPath(); g.ellipse(x, y + 5, R * 0.8, R, 0, 0, 7); g.fill();
      const hg = g.createRadialGradient(x, y - 6, 2, x, y, R); hg.addColorStop(0, '#5e0f45'); hg.addColorStop(1, '#a3296f'); g.fillStyle = hg; g.beginPath(); g.ellipse(x, y, R * 0.8, R, 0, 0, 7); g.fill(); } }),
  dark: cvs(64, 256, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#3c0f66'], [1, '#7d32b8']]); g.fillRect(0, 0, w, h); }),
  tunnel: cvs(512, 256, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#8f5fd6'], [0.5, '#c39af0'], [1, '#8f5fd6']]); g.fillRect(0, 0, w, h);
    g.globalCompositeOperation = 'lighter'; for (let i = 0; i < 10; i++) { const x = rnd() * w; g.fillStyle = `rgba(255,190,255,${0.05 + rnd() * 0.08})`; g.fillRect(x, 0, 2 + rnd() * 8, h); } g.globalCompositeOperation = 'source-over';
    for (let r = 0; r < 4; r++) for (let i = 0; i < 8; i++) { const x = (i + 0.5 + (r % 2) * 0.5) * w / 8, y = (r + 0.5) * h / 4, R = 9;
      g.fillStyle = 'rgba(235,215,255,0.9)'; g.beginPath(); g.arc(x, y + 2, R, 0, 7); g.fill(); g.fillStyle = '#3a1060'; g.beginPath(); g.arc(x, y, R, 0, 7); g.fill(); } }),
  gold: cvs(256, 256, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#a8560f'], [0.25, '#f5a83a'], [0.45, '#ffe9a6'], [0.6, '#f4a63c'], [1, '#9a4c10']]); g.fillRect(0, 0, w, h); }),
  goldring: cvs(1024, 128, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#a8560f'], [0.2, '#f6b04a'], [0.35, '#ffe39a'], [0.5, '#e8902c'], [0.75, '#ffcc66'], [1, '#8a4210']]); g.fillRect(0, 0, w, h);
    for (let i = 0; i < 8; i++) { const x = (i + 0.5) * w / 8; g.fillStyle = 'rgba(255,250,215,0.95)'; g.fillRect(x - 26, 16, 52, 30); g.fillStyle = 'rgba(255,230,150,0.35)'; g.fillRect(x - 36, 8, 72, 46); } }),
  goldbar: cvs(64, 64, (g, w, h) => { g.fillStyle = grad(g, 0, 0, w, 0, [[0, '#b8661a'], [0.3, '#f7b54a'], [0.45, '#fff0b8'], [0.6, '#f4a63c'], [1, '#a8560f']]); g.fillRect(0, 0, w, h); }),
  pipe: cvs(64, 256, (g, w, h) => { g.fillStyle = grad(g, 0, 0, w, 0, [[0, '#4d1a8f'], [0.3, '#9b5ae6'], [0.42, '#f2d4ff'], [0.55, '#a865ee'], [1, '#4d1a8f']]); g.fillRect(0, 0, w, h); }),
  tank: cvs(256, 256, (g, w, h) => { g.fillStyle = grad(g, 0, 0, w, 0, [[0, '#d99ad8'], [0.5, '#fbe0f6'], [1, '#d99ad8']]); g.fillRect(0, 0, w, h); }),
  foam: cvs(64, 64, (g, w, h) => { g.fillStyle = grad(g, 0, 0, 0, h, [[0, '#ffffff'], [1, '#c9c3f2']]); g.fillRect(0, 0, w, h); }),
  silver: cvs(64, 256, (g, w, h) => { g.fillStyle = grad(g, 0, 0, w, 0, [[0, '#9a86c8'], [0.4, '#f1e8ff'], [0.6, '#d7c8f5'], [1, '#8d77bd']]); g.fillRect(0, 0, w, h); }),
  towelP: cvs(256, 256, (g, w, h) => { g.fillStyle = '#8b5ad8'; g.fillRect(0, 0, w, h); g.fillStyle = '#efe6ff'; g.fillRect(0, h * 0.78, w, 10); g.fillRect(0, h * 0.86, w, 6); g.fillRect(0, h * 0.14, w, 10); }),
  towelK: cvs(256, 256, (g, w, h) => { g.fillStyle = '#f07ab9'; g.fillRect(0, 0, w, h); g.fillStyle = '#ffe9f4'; g.fillRect(0, h * 0.78, w, 10); g.fillRect(0, h * 0.86, w, 6); g.fillRect(0, h * 0.14, w, 10); }),
  sock: cvs(128, 256, (g, w, h) => { g.fillStyle = '#fbf8ff'; g.fillRect(0, 0, w, h); g.fillStyle = '#f0f0fa'; for (let y = 0; y < h; y += 4) g.fillRect(0, y, w, 1);
    g.fillStyle = '#ee4f9c'; g.fillRect(0, 12, w, 11); g.fillRect(0, 30, w, 7); g.fillRect(0, h * 0.56, w, h * 0.14); g.fillRect(0, h - 40, w, 40);
    g.beginPath(); const hx = w * 0.25, hy = h * 0.33, r = 9; g.moveTo(hx, hy + r); g.bezierCurveTo(hx - 2 * r, hy - r * 0.2, hx - r, hy - 1.6 * r, hx, hy - 0.6 * r); g.bezierCurveTo(hx + r, hy - 1.6 * r, hx + 2 * r, hy - 0.2 * r, hx, hy + r); g.fill(); }),
};
const PIC = {}; const tl = new THREE.TextureLoader();
const loadRaw = async (f) => { const t = await tl.loadAsync(f); t.colorSpace = THREE.NoColorSpace; t.anisotropy = 8; return t; };
// one shader family for all scenery: code material (repeating) + baked picture pixels (weight = baked alpha) + the exit light (world z)
const GLOW = { uGlow: { value: new THREE.Vector3(Z_EXIT + 5, Z_EXIT, 0.45) }, uTime: { value: 0 } };
// sharpness guard: x = phone-frame px per canvas px, y = magnification (phone px per picture px) where the painted pixels start to hand over
const SHARP = { uSharp: { value: new THREE.Vector2(915 / (H * renderer.getPixelRatio()), +(q.get('sharp') ?? 1.3)) } };
const sceneryMat = (base, rep, opts = {}) => new THREE.ShaderMaterial({
  side: THREE.DoubleSide, transparent: !!opts.transparent, depthWrite: !opts.transparent,
  uniforms: { uBase: { value: base }, uRep: { value: new THREE.Vector2(...rep) }, uBake: { value: null }, uBakeOn: { value: 0 }, uScroll: { value: new THREE.Vector2(...(opts.scroll ?? [0, 0])) },
    uTint: { value: new THREE.Color(...(opts.tint ?? [1, 1, 1])) }, uAlpha: { value: opts.alpha ?? 1 }, uDen: { value: null }, ...GLOW, ...SHARP },
  vertexShader: 'varying vec2 vUv; varying vec3 vW; void main(){ vUv = uv; vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }',
  fragmentShader: `uniform sampler2D uBase; uniform vec2 uRep; uniform sampler2D uBake; uniform float uBakeOn; uniform vec2 uScroll; uniform vec3 uTint; uniform float uAlpha; uniform vec3 uGlow; uniform float uTime;
    uniform sampler2D uDen; uniform vec2 uSharp; varying vec2 vUv; varying vec3 vW;
    void main(){ vec2 su = vUv + uScroll * uTime; vec3 c = texture2D(uBase, su * uRep).rgb * uTint;
      if (uBakeOn > 0.5) { vec4 b = texture2D(uBake, su); vec4 dd = texture2D(uDen, vUv); float pd = (dd.r + dd.g / 255.0) * 4000.0;   // picture px per world unit
        float magE = uSharp.x / max(max(length(dFdx(vW)), length(dFdy(vW))), 1e-6) / max(pd, 1.0);                         // phone px per picture px here
        c = mix(c, b.rgb, dd.b * (1.0 - smoothstep(uSharp.y, uSharp.y * 2.3, magE))); }
      c = mix(c, vec3(1.0, 0.97, 0.92), uGlow.z * pow(smoothstep(uGlow.x, uGlow.y, vW.z), 1.6));
      gl_FragColor = vec4(c, uAlpha); }` });

// ---------------- the scenery: Blender GLB ----------------
const gl = await new GLTFLoader().loadAsync('section.glb');
const MESH = []; gl.scene.traverse((o) => { if (o.isMesh) MESH.push(o); });
const famOf = (n) => n.startsWith('tunnel_') ? 'tunnel' : n.startsWith('ring_') ? 'ring' : n === 'arch' ? 'arch' : /^(bulkhead|wall_|ledge)/.test(n) ? 'pink' : /^(backwall|ceiling)/.test(n) ? 'dark'
  : n.endsWith('_throat') ? 'throat' : n.startsWith('outlet_') ? 'gold' : n.startsWith('fall_') ? 'fall' : n.startsWith('pipe_') ? 'pipe' : /^(collar_|tower_rim|rail_)/.test(n) ? 'gold'
  : n === 'tower' ? 'tank' : n.startsWith('towerfoam') ? 'foam' : n.startsWith('pod_') ? 'silver' : n.startsWith('towel_') ? 'towel' : n.startsWith('sock_') ? 'sock' : 'pink';
const size = (o) => { o.geometry.computeBoundingBox(); const b = o.geometry.boundingBox; return b.getSize(new THREE.Vector3()); };

