import json, struct, collections
b=open('public/section/section.glb','rb').read(); n=struct.unpack('<I',b[12:16])[0]; J=json.loads(b[20:20+n])
fam=collections.Counter(); ex={}
for nd in J['nodes']:
    if 'mesh' not in nd: continue
    nm=nd.get('name'); m=J['meshes'][nd['mesh']]; mn=[1e9]*3; mx=[-1e9]*3
    for p in m['primitives']:
        a=J['accessors'][p['attributes']['POSITION']]; mn=[min(x,y) for x,y in zip(mn,a['min'])]; mx=[max(x,y) for x,y in zip(mx,a['max'])]
    k=nm.split('_')[0]; fam[k]+=1; ex.setdefault(k,[]).append((nm,round(mn[2],1),round(mx[2],1),round(mn[1],2),round(mx[1],2)))
print(fam)
for k in ['river','water','pool','floor','wall','bulkhead','tunnel']:
    if k in ex: print(k, ex[k][:4])
EOF
