float sp = sin(uT * 7.5); p.y += uBobA * sp * sp;
float wp = smoothstep(0.17, 0.27, p.y); vec3 pp = vec3(0.0, 0.19, 0.05); vec3 r = p - pp;
r = b31rot(r, vec3(1.0, 0.0, 0.0), uPom.x * wp); r = b31rot(r, vec3(0.0, 0.0, 1.0), uPom.y * wp); p = pp + r;
float sq = 1.0 + 0.03 * uSwim * sin(uT * 15.0); p.y = (p.y + 0.5) * sq - 0.5; p.xz /= sqrt(sq);
vec3 transformed = p;`;
